import{_ as e}from"./chunks/maintenance-pwr.pc.ko.DU4C6rG6.js";import{_ as a,o as t,c as r,a5 as n}from"./chunks/framework.BYXPg_yw.js";const m=JSON.parse('{"title":"외부 포트 전원 켜기","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/interface/port-power.md","filePath":"ko/manual/interface/port-power.md","lastUpdated":1792139892000}'),l={name:"ko/manual/interface/port-power.md"};function c(i,o,s,d,p,h){return t(),r("div",null,[...o[0]||(o[0]=[n('<h1 id="외부-포트-전원-켜기" tabindex="-1">외부 포트 전원 켜기 <a class="header-anchor" href="#외부-포트-전원-켜기" aria-label="Permalink to &quot;외부 포트 전원 켜기&quot;">​</a></h1><p>페이로드를 외부 포트에 물렸는데 아무 반응이 없다면, 대개 <strong>그 포트로 나가는 전원이 꺼져 있는</strong> 것입니다. 포트의 전원은 커넥터를 꽂는 것만으로 살아나지 않고 <strong>앱에서 켜야</strong> 합니다.</p><p>배선과 핀 배열은 <a href="/RBQ/nightly/ko/manual/interface/external-port.html">외부 포트 정보</a>에, 케이블은 <a href="/RBQ/nightly/ko/manual/product-descriptions/accessories.html#payload-cabling">액세서리</a>에 있습니다.</p><h2 id="where" tabindex="-1">어디에서 켜나 <a class="header-anchor" href="#where" aria-label="Permalink to &quot;어디에서 켜나 {#where}&quot;">​</a></h2><p>외부 포트 전원은 모두 <strong>정비 → 전원 / 시스템</strong>에서 켭니다. 모든 사용자가 열 수 있습니다. 사용자가 바깥에서 물리는 포트는 <code>상단 포트</code> 섹션에 모여 있습니다. 화면 전체 설명은 <a href="/RBQ/nightly/ko/manual/gui/maintenance.html#power">정비 › 전원 / 시스템</a>에 있습니다.</p><p><img src="'+e+'" alt="정비 → 전원 / 시스템"></p><h2 id="48v" tabindex="-1">48V 포트 켜기 <a class="header-anchor" href="#48v" aria-label="Permalink to &quot;48V 포트 켜기 {#48v}&quot;">​</a></h2><p><code>POWER</code>(2핀)와 <code>PWR-CAN</code>(4핀)처럼 배터리 전압을 그대로 쓰는 포트는 48V 레일에 물려 있습니다.</p><ol><li><strong>정비 → 전원 / 시스템</strong>을 엽니다.</li><li><code>상단 포트</code> 섹션의 <code>EXTERN (48V)</code> 행에서 <strong><code>켜기</code></strong> 를 누릅니다. 외부 확장 포트로 나가는 전원입니다. CAN-FD 기체에는 이 행이 없고 <code>ARM · ADDON (48V)</code> 하나입니다.</li><li>확인 창 <code>정말 켤까요?</code>에서 <strong><code>켜기</code></strong> 로 확정합니다.</li><li>같은 행에 표시되는 <strong>현재 전압</strong>이 올라오는지 확인합니다.</li></ol><p>애드온 장치가 <code>ARM · ADDON (48V)</code> 쪽이라면 그 행을 켭니다.</p><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">주의</p><p><code>ARM · ADDON (48V)</code> 는 팔과 애드온이 <strong>PDU 포트 하나를 함께</strong> 씁니다. 이 레일을 끄면 팔 전원도 같이 나가므로, 끄기 전에 팔이 정지 상태인지 확인하세요.</p></div></div><p>48V 계열이 내보내는 전압은 <strong>배터리 전압 그대로</strong>라 잔량에 따라 42.0~58.4 V 사이에서 변합니다. 정전압이 필요한 페이로드에는 컨버터를 따로 두세요.</p><h2 id="12v" tabindex="-1">12V 포트 켜기 <a class="header-anchor" href="#12v" aria-label="Permalink to &quot;12V 포트 켜기 {#12v}&quot;">​</a></h2><p><code>상단 포트</code> 섹션의 <code>12V 포트 1</code>~<code>4</code> 토글을 한 번 탭해 켭니다. 무엇을 물리느냐가 로봇마다 달라 번호로만 부릅니다. 어느 커넥터가 몇 번인지 보여 주는 그림은 섹션 제목 옆 <code>? 도움말</code>에 추후 추가될 예정입니다. 끌 때는 <code>정말 끌까요?</code>를 한 번 더 묻습니다 — 통신장비가 연결된 포트를 끄면 앱과의 연결이 끊길 수 있습니다.</p><h2 id="not-working" tabindex="-1">켰는데도 안 될 때 <a class="header-anchor" href="#not-working" aria-label="Permalink to &quot;켰는데도 안 될 때 {#not-working}&quot;">​</a></h2><ul><li><strong>토글이 회색이고 눌리지 않습니다</strong> — 레일 상태를 아직 못 받은 것입니다. 로봇 연결을 먼저 확인하세요(<a href="/RBQ/nightly/ko/manual/gui/connection.html">연결</a>).</li><li><strong>켰는데 바로 안 바뀝니다</strong> — 토글은 로봇 PDU가 보고한 <strong>실제 상태</strong>를 표시합니다. 반영에 1초 정도 걸립니다.</li><li><strong>전압이 올라오지 않습니다</strong> — 커넥터 체결과 케이블을 확인하세요 (<a href="/RBQ/nightly/ko/manual/maintenance/connector.html">커넥터 탈부착</a>).</li><li><strong>전원은 들어오는데 장치가 안 켜집니다</strong> — 포트별 최대 전류를 넘지 않는지 확인하세요: <code>POWER</code> 5 A · <code>PWR-CAN</code> 10 A · <code>12V/LAN</code> 2~3 A (<a href="/RBQ/nightly/ko/manual/interface/external-port.html#user-port-pin-map">핀맵</a>).</li></ul><h2 id="still-stuck" tabindex="-1">그래도 해결되지 않으면 <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;그래도 해결되지 않으면 {#still-stuck}&quot;">​</a></h2><p>어느 포트에 무엇을 물렸는지, 그리고 전원 화면에 표시된 전압을 함께 알려주시면 확인이 빠릅니다.</p><p><strong>→ <a href="/RBQ/nightly/ko/manual/support/">기술지원 요청</a></strong></p>',19)])])}const f=a(l,[["render",c]]);export{m as __pageData,f as default};
